    session_id TEXT, user_id TEXT, page TEXT, created_at TEXT DEFAULT (datetime('now'))
  );

CREATE TABLE IF NOT EXISTS ab_experiments (
    id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT DEFAULT '',
    variants TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), status TEXT DEFAULT 'active'
  );

CREATE TABLE IF NOT EXISTS app_waitlist (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, source TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')));

CREATE TABLE IF NOT EXISTS auto_topup_config (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id TEXT NOT NULL UNIQUE,
      enabled INTEGER DEFAULT 0,
      threshold INTEGER DEFAULT 10,
      bundle_type TEXT DEFAULT 'standard',
      created_at TEXT DEFAULT (datetime('now', '+8 hours')),
      updated_at TEXT DEFAULT (datetime('now', '+8 hours')),
      FOREIGN KEY (user_id) REFERENCES users(id)
    );

CREATE TABLE IF NOT EXISTS auto_topup_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id TEXT NOT NULL,
      bundle_type TEXT NOT NULL,
      credits_added INTEGER NOT NULL,
      amount_paid REAL NOT NULL,
      status TEXT DEFAULT 'completed' CHECK(status IN ('completed','failed','pending')),
      trigger TEXT DEFAULT 'auto' CHECK(trigger IN ('auto','manual')),
      created_at TEXT DEFAULT (datetime('now', '+8 hours')), "amount_paid_cents" INTEGER,
      FOREIGN KEY (user_id) REFERENCES users(id)
    );

