CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT DEFAULT '', email TEXT DEFAULT '', rating INTEGER DEFAULT 0, comment TEXT NOT NULL, page TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')));

CREATE TABLE IF NOT EXISTS newsletter_subscribers (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, interests TEXT DEFAULT '[]', source TEXT DEFAULT 'web', subscribed_at TEXT DEFAULT (datetime('now')), is_active INTEGER DEFAULT 1, unsubscribed_at TEXT);

CREATE TABLE IF NOT EXISTS pageviews (id INTEGER PRIMARY KEY AUTOINCREMENT, page TEXT NOT NULL, referrer TEXT DEFAULT '', title TEXT DEFAULT '', ip_hash TEXT DEFAULT '', user_agent TEXT DEFAULT '', viewed_at TEXT DEFAULT (datetime('now')));

CREATE TABLE IF NOT EXISTS partner_members (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      partner_id TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'coach',
      status TEXT DEFAULT 'active',
      created_at TEXT DEFAULT (datetime('now')), commission_rate REAL DEFAULT 0.75, updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (partner_id) REFERENCES partner_venues(id)
    );

CREATE TABLE IF NOT EXISTS penalty_logs (
  id TEXT PRIMARY KEY,
  booking_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('late_cancel', 'no_show')),
  class_cost INT DEFAULT 0,
  penalty_credits INT DEFAULT 0,
  status TEXT DEFAULT 'applied' CHECK(status IN ('applied', 'waived')),
  reason TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (booking_id) REFERENCES bookings(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
);

