      );

CREATE TABLE IF NOT EXISTS venue_rentals (
  id TEXT PRIMARY KEY,
  venue_id TEXT NOT NULL,
  coach_id TEXT NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  price_hkd REAL NOT NULL,
  status TEXT DEFAULT 'pending' CHECK(status IN ('pending','confirmed','cancelled','completed')),
  created_at TEXT DEFAULT (datetime('now')), commission_rate REAL DEFAULT 0.15, commission_amount REAL DEFAULT 0, venue_earned REAL DEFAULT 0, "price_hkd_cents" INTEGER, "commission_amount_cents" INTEGER,
  FOREIGN KEY (venue_id) REFERENCES partner_venues(id),
  FOREIGN KEY (coach_id) REFERENCES users(id)
);

